fn allocation_capture_keeps_existing_and_new_original_failures(){
 use semio_framework_value_native_owned::native_decoding::NativeDecodeAllocationOutcome;
 let f:serde_json::Value=serde_json::from_str(include_str!("encoded-text.json")).unwrap();let row=&f["occupied"];let first=ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,row["first"].as_str().unwrap().to_owned());let second=ValueError::new(semio_framework_value::ValueRefusalKind::WorkLimit,row["second"].as_str().unwrap().to_owned());let first_pointer=first.message.as_ptr();let second_pointer=second.message.as_ptr();let outcome=|error|NativeDecodeAllocationOutcome{request:None,admitted:false,primary:Some(error),quote_refusal:None,extent_refusal:None,settlement_refusal:None,actual:None};let mut frame=super::super::NativeSnapshotDecodeAllocation::default();frame.expected=Some(row["existingExpected"].as_u64().unwrap()as usize);frame.pending=Some(super::super::NativeSnapshotAllocationFailure::Decode(outcome(first)));
 let returned=frame.capture(outcome(second),row["extent"].as_u64().unwrap()as usize).unwrap_err();let Some(super::super::NativeSnapshotAllocationFailure::Decode(stored))=frame.pending.as_ref()else{panic!("first allocation owner lost")};let super::super::NativeSnapshotAllocationFailure::Decode(returned)=returned else{panic!("second allocation owner changed direction")};assert_eq!(frame.expected,Some(row["existingExpected"].as_u64().unwrap()as usize));assert_eq!(stored.primary.as_ref().unwrap().message.as_ptr(),first_pointer);assert_eq!(returned.primary.as_ref().unwrap().message.as_ptr(),second_pointer);let grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:1<<20,maximum_capacity_bytes:1<<20,maximum_release_bytes:1<<20,maximum_depth:256};close(frame,grant);close(returned,grant);
}

#[test]
fn combined_text_birth_uses_exact_backing_and_skips_empty_allocation(){
 use semio_framework_value_native_owned::native_decoding::{NativeDecodeControl,NativeAllocationEvent};struct Physical{grant:RetainedCloneGrant,submitted:RetainedCloneProgress}impl OriginalConstructionRecipient for Physical{type Context<'t,'s>=() where 's:'t;fn validate_context<'t,'s>(&self,_:&())->Result<(),ValueError>where 's:'t{Ok(())}fn source_turn<'t,'s>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 's:'t{None}fn submitted<'t,'s>(&self,_:&())->RetainedCloneProgress where 's:'t{self.submitted}fn grant<'a,'t,'s>(&mut self,_:&mut (),quote:OriginalConstructionGrant<'a>)->OriginalConstructionGrantComplete<'a>where 's:'t{quote.complete((||->Result<RetainedCloneGrant,ValueError>{Ok(self.grant)})())}fn accept<'a,'t,'s>(&mut self,_:&mut (),receipt:OriginalConstructionAccept<'a>)->OriginalConstructionAcceptComplete<'a>where 's:'t{let grant:RetainedCloneGrant=receipt.grant();let progress:RetainedCloneProgress=receipt.progress();receipt.complete((||->Result<(),ValueError>{assert_eq!(grant,self.grant);self.submitted=self.submitted.checked_add(progress)?;Ok(())})())}}struct Work;impl OriginalWorkRecipient for Work{type Context<'t,'s>=() where 's:'t;fn validate_context<'t,'s>(&self,_:&())->Result<(),ValueError>where 's:'t{Ok(())}fn source_turn<'t,'s>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 's:'t{None}fn admits<'r,'t,'s>(&mut self,_:&mut (),quote:OriginalWorkQuote<'r>,observed:u64,additional:u64)->OriginalWorkQuoteComplete<'r>where 's:'t{quote.complete((||->Result<bool,ValueError>{Ok(observed.checked_add(additional).is_some_and(|total|total<=1_000_000))})())}fn settle_partial<'r,'t,'s>(&mut self,_:&mut (),check:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r>where 's:'t{let _:u64=u64::try_from(check.delta()).unwrap();check.complete((||->Result<(),ValueError>{Ok(())})())}fn recover_partial<'r,'t,'s>(&mut self,_:&mut (),check:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r>where 's:'t{check.complete(Ok(()))}}
 for bytes in [0usize,8]{let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:std::mem::size_of::<String>(),maximum_capacity_bytes:bytes,maximum_release_bytes:0,maximum_depth:1};let pending=std::sync::Mutex::new(None);let quotes=AtomicUsize::new(0);let submitted=AtomicUsize::new(0);let mut port=|event:NativeAllocationEvent|match event{NativeAllocationEvent::Admit(_)=>panic!("unexpected historical admission in physical allocation law"),NativeAllocationEvent::Quote(request)=>{quotes.fetch_add(1,Ordering::Relaxed);assert!(pending.lock().unwrap().replace(request).is_none());Ok(())},NativeAllocationEvent::Post{request,actual}=>{assert_eq!(pending.lock().unwrap().take(),Some(request));submitted.fetch_add(actual,Ordering::Relaxed);Ok(())},NativeAllocationEvent::Cancel(request)=>{assert_eq!(pending.lock().unwrap().take(),Some(request));Ok(())}};let mut observe=|_|true;let mut allocation_authority=NativeAllocationAuthority::new(Port(port));allocation_authority.with_send_loan(&mut (),|allocation_loan|{let mut native=NativeDecodeControl::new_forwarded(bytes,&mut observe,allocation_loan);let mut physical=Physical{grant,submitted:Default::default()};let mut work=Work;let mut marker=super::super::NativeSnapshotEffectProgress::default();let mut unwind=None;let mut allocation=super::super::NativeSnapshotDecodeAllocation::default();let mut output=None;let mut rauth14=OriginalConstructionAuthority::new(super::ByRef(&mut physical));let mut wauth14=OriginalWorkAuthority::new(super::ByRef(&mut work));let turn={rauth14.with_loan(&mut (),|rl|wauth14.with_loan(&mut (),|wl|native.with_construction_recipient(rl,|native|native.with_work_recipient(wl,|native|{let mut owner=super::super::NativeSnapshotDecodeOwner::new(native,grant);Ok::<_,ValueError>(owner.allocate_string(bytes,&mut output,&mut marker,&mut unwind,&mut allocation,1))})))).unwrap().unwrap()}.unwrap();turn.result.unwrap();assert_eq!(turn.work,1);assert_eq!(native.owned_bytes(),bytes);assert_eq!(physical.submitted.retained_capacity_bytes,bytes);assert_eq!(physical.submitted.copied_bytes,std::mem::size_of::<String>());assert_eq!(output.as_ref().unwrap().capacity(),bytes);assert!(unwind.is_none()&&allocation.actual.is_none()&&allocation.unwind.is_none()&&allocation.pending.is_none()&&allocation.collision.is_none());drop(native);assert_eq!(quotes.load(Ordering::Relaxed),usize::from(bytes!=0));assert_eq!(submitted.load(Ordering::Relaxed),bytes);assert!(pending.lock().unwrap().is_none());let close_grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};close(output.take().unwrap(),close_grant);close(allocation,close_grant);}).unwrap();assert!(allocation_authority.into_port().is_ok());}
}


#[test]fn exact_vector_quote_denial_keeps_output_and_allocation_unborn(){use semio_framework_value_native_owned::native_decoding::{NativeDecodeControl,NativeAllocationEvent};struct Physical{grant:RetainedCloneGrant,submitted:RetainedCloneProgress}impl OriginalConstructionRecipient for Physical{type Context<'t,'s>=() where 's:'t;fn validate_context<'t,'s>(&self,_:&())->Result<(),ValueError>where 's:'t{Ok(())}fn source_turn<'t,'s>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 's:'t{None}fn submitted<'t,'s>(&self,_:&())->RetainedCloneProgress where 's:'t{self.submitted}fn grant<'a,'t,'s>(&mut self,_:&mut (),quote:OriginalConstructionGrant<'a>)->OriginalConstructionGrantComplete<'a>where 's:'t{quote.complete((||->Result<RetainedCloneGrant,ValueError>{Ok(self.grant)})())}fn accept<'a,'t,'s>(&mut self,_:&mut (),receipt:OriginalConstructionAccept<'a>)->OriginalConstructionAcceptComplete<'a>where 's:'t{let _:RetainedCloneGrant=receipt.grant();let _:RetainedCloneProgress=receipt.progress();receipt.complete((||->Result<(),ValueError>{panic!("denied backing cannot post")})())}}struct Work;impl OriginalWorkRecipient for Work{type Context<'t,'s>=() where 's:'t;fn validate_context<'t,'s>(&self,_:&())->Result<(),ValueError>where 's:'t{Ok(())}fn source_turn<'t,'s>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 's:'t{None}fn admits<'r,'t,'s>(&mut self,_:&mut (),quote:OriginalWorkQuote<'r>,observed:u64,additional:u64)->OriginalWorkQuoteComplete<'r>where 's:'t{quote.complete((||->Result<bool,ValueError>{if observed.checked_add(additional).is_some_and(|total|total<=1_000_000){panic!("denied backing cannot reserve work")}Ok(false)})())}fn settle_partial<'r,'t,'s>(&mut self,_:&mut (),check:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r>where 's:'t{let _:u64=u64::try_from(check.delta()).unwrap();check.complete((||->Result<(),ValueError>{Ok(())})())}fn recover_partial<'r,'t,'s>(&mut self,_:&mut (),check:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r>where 's:'t{check.complete(Ok(()))}}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:std::mem::size_of::<Vec<u64>>(),maximum_capacity_bytes:0,maximum_release_bytes:0,maximum_depth:1};let events=AtomicUsize::new(0);let mut port=|_:NativeAllocationEvent|{events.fetch_add(1,Ordering::Relaxed);Ok(())};let mut observe=|_|true;let mut allocation_authority=NativeAllocationAuthority::new(Port(port));allocation_authority.with_send_loan(&mut (),|allocation_loan|{let mut native=NativeDecodeControl::new_forwarded(16,&mut observe,allocation_loan);let mut physical=Physical{grant,submitted:Default::default()};let mut work=Work;let mut marker=super::super::NativeSnapshotEffectProgress::default();let mut unwind=None;let mut allocation=super::super::NativeSnapshotDecodeAllocation::default();let mut output=None;let mut rauth15=OriginalConstructionAuthority::new(super::ByRef(&mut physical));let mut wauth15=OriginalWorkAuthority::new(super::ByRef(&mut work));let turn={rauth15.with_loan(&mut (),|rl|wauth15.with_loan(&mut (),|wl|native.with_construction_recipient(rl,|native|native.with_work_recipient(wl,|native|{let mut owner=super::super::NativeSnapshotDecodeOwner::new(native,grant);Ok::<_,ValueError>(owner.allocate_vector::<u64>(2,&mut output,&mut marker,&mut unwind,&mut allocation,1))})))).unwrap().unwrap()}.unwrap();assert_eq!(turn.work,0);assert!(turn.result.is_err());assert!(output.is_none());assert_eq!(native.owned_bytes(),0);assert!(!marker.performed);assert!(allocation.actual.is_none()&&allocation.unwind.is_none()&&allocation.pending.is_none()&&allocation.collision.is_none());drop(native);assert_eq!(events.load(Ordering::Relaxed),0);let grant=RetainedCloneGrant{maximum_items:1024,maximum_copy_bytes:65536,maximum_capacity_bytes:65536,maximum_release_bytes:65536,maximum_depth:64};close(turn.result.unwrap_err(),grant);close(allocation,grant);}).unwrap();assert!(allocation_authority.into_port().is_ok());}

#[test]
fn encoder_owned_settlement_records_wallet_once_after_post_unwind(){
 use std::sync::atomic::{AtomicUsize,Ordering};
 struct Physical<'a>{grant:RetainedCloneGrant,calls:&'a AtomicUsize}impl OriginalConstructionRecipient for Physical<'_>{type Context<'t,'s>=() where 's:'t;fn validate_context<'t,'s>(&self,_:&())->Result<(),ValueError>where 's:'t{Ok(())}fn source_turn<'t,'s>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 's:'t{None}fn submitted<'t,'s>(&self,_:&())->RetainedCloneProgress where 's:'t{Default::default()}fn grant<'a,'t,'s>(&mut self,_:&mut (),quote:OriginalConstructionGrant<'a>)->OriginalConstructionGrantComplete<'a>where 's:'t{quote.complete((||->Result<RetainedCloneGrant,ValueError>{Ok(self.grant)})())}fn accept<'a,'t,'s>(&mut self,_:&mut (),receipt:OriginalConstructionAccept<'a>)->OriginalConstructionAcceptComplete<'a>where 's:'t{let _:RetainedCloneGrant=receipt.grant();let _:RetainedCloneProgress=receipt.progress();let calls=self.calls.fetch_add(1,Ordering::Relaxed);let done=receipt.complete(Ok(()));if calls==0{panic!("fixture original physical post")}done}}
 struct Work;impl OriginalWorkRecipient for Work{type Context<'t,'s>=() where 's:'t;fn validate_context<'t,'s>(&self,_:&())->Result<(),ValueError>where 's:'t{Ok(())}fn source_turn<'t,'s>(&self,_:&())->Option<OriginalSourceTurnIdentity>where 's:'t{None}fn admits<'r,'t,'s>(&mut self,_:&mut (),quote:OriginalWorkQuote<'r>,_:u64,_:u64)->OriginalWorkQuoteComplete<'r>where 's:'t{quote.complete((||->Result<bool,ValueError>{Ok(true)})())}fn settle_partial<'r,'t,'s>(&mut self,_:&mut (),check:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r>where 's:'t{let _:u64=u64::try_from(check.delta()).unwrap();check.complete((||->Result<(),ValueError>{Ok(())})())}fn recover_partial<'r,'t,'s>(&mut self,_:&mut (),check:OriginalWorkPartialCheck<'r>)->OriginalWorkPartialCheckComplete<'r>where 's:'t{check.complete(Ok(()))}}
 let f:serde_json::Value=serde_json::from_str(include_str!("cursor-effect.json")).unwrap();let _=f;let grant=super::fixture_grant();let calls=AtomicUsize::new(0);let mut physical=Physical{grant,calls:&calls};let mut work=Work;let mut callback=|_|true;let mut native=semio_framework_value::NativeEncodeControl::new_retained(&mut callback);let mut settlement=None;let mut rauth16=OriginalConstructionAuthority::new(super::ByRef(&mut physical));let mut wauth16=OriginalWorkAuthority::new(super::ByRef(&mut work));
 {rauth16.with_loan(&mut (),|rl|wauth16.with_loan(&mut (),|wl|native.with_construction_recipient(rl,|native|native.with_work_recipient(wl,|native|{let mut owner=super::super::NativeSnapshotEncodeOwner::new(native,grant);owner.begin_original_settlement(&mut settlement,RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:8,maximum_depth:1,..Default::default()},1)?;let actual=RetainedCloneProgress{copied_items:1,copied_bytes:8,..Default::default()};assert!(owner.record_original_effect(&mut settlement,actual,true,Some(1))?);let original=std::panic::catch_unwind(||std::panic::panic_any(42usize)).unwrap_err();assert!(settlement.as_mut().unwrap().retain_operation_unwind(original).is_ok());let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||owner.settle_original_effect(&mut settlement)));assert!(result.is_err());assert!(!semio_framework_value::retirement::RetireOwned::retirement_ready(settlement.as_ref().unwrap()));assert_eq!(owner.progress(),actual);owner.settle_original_effect(&mut settlement)?;let receipt=super::super::NativeSnapshotEncodeSettlement::take_receipt(&mut settlement)?;assert_eq!(receipt.progress(),actual);assert_eq!(owner.progress(),actual);close(receipt,grant);let resumed=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||super::super::NativeSnapshotEncodeSettlement::resume_operation_unwind(&mut settlement)));assert_eq!(*resumed.unwrap_err().downcast::<usize>().unwrap(),42);assert!(settlement.is_none());Ok::<_,ValueError>(())})))).unwrap().unwrap()}.unwrap();assert_eq!(calls.load(Ordering::Relaxed),1);
}

#[test]fn marker_reset_requires_empty_original_settlement(){let rows:serde_json::Value=serde_json::from_str(include_str!("🧭️marker.json")).unwrap();let mut marker=super::super::NativeSnapshotEffectProgress::default();marker.performed=true;marker.physical=RetainedCloneProgress{copied_items:1,..Default::default()};assert_eq!(rows[0]["mayReset"],true);marker.reset_completed().unwrap();assert!(!marker.performed);assert_eq!(marker.physical,Default::default());}
